# -*- coding: utf-8 -*-
# N2 中文 tambahan 4 (3問) + 統合理解 tambahan (2問)
P1 = "Cari kalimat pendapat penulis (biasanya setelah しかし/だが/つまり) lalu cocokkan dengan parafrasenya."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawabannya hampir selalu di sana."
P3 = "Pilihan yang terlalu ekstrem (すべて・必ず・全く) atau memuat hal yang tak ada di teks hampir pasti salah."
PT = "Soal 統合: tandai pendapat A dan B secara terpisah, lalu cari titik temu/perbedaannya."
JN = 'Teks menengah (内容理解・中文)'; JT = 'Bacaan gabungan (統合理解)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan pendapat penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
def X(jp, id, qs):
    return dict(slot='tou', jenis=JT, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, PT) for (q, ok, w, al, bu) in qs])
B = [
 C('最近、「推し活」という言葉をよく耳にする。好きな歌手や俳優、キャラクターを応援する活動のことで、コンサートに行ったり、関連グッズを集めたりする人が多い。\n　推し活の魅力は、好きなものがあることで、日々の生活にハリが出る点にある。仕事がつらい日でも、「今度のライブまで頑張ろう」と思えるという人は少なくない。また、同じ対象を好きな人同士で交流が生まれ、新しい友人ができることもある。\n　一方で、お金や時間を使いすぎて、生活に支障が出る例もある。楽しむためには、自分の生活を壊さない範囲で行うという線引きが欠かせない。好きなことは、人生を豊かにするが、それに振り回されては意味がないからだ。',
   'Belakangan sering terdengar kata "oshi-katsu". Yaitu kegiatan mendukung penyanyi, aktor, atau karakter favorit, dan banyak orang menonton konser atau mengoleksi merchandise terkait.\n Daya tarik oshi-katsu adalah adanya hal yang disukai membuat hidup sehari-hari bersemangat. Tak sedikit orang yang bahkan di hari kerja berat berpikir "berusaha sampai live berikutnya". Juga timbul pergaulan antarpenyuka objek sama dan kadang punya teman baru.\n Di sisi lain ada contoh terlalu banyak memakai uang dan waktu sehingga hidup terganggu. Agar bisa menikmati, batasan melakukannya dalam batas yang tak merusak hidup diperlukan. Sebab hal yang disukai memperkaya hidup, tetapi tak berarti jika kita diombang-ambingkannya.',
   [('推し活の魅力として挙げられているものはどれか。','生活にハリが出て、新しい友人ができること',['お金が増えること','仕事が楽になること','有名になれること'],'Daya tarik.','日々の生活にハリが出る…新しい友人ができる'),
    ('推し活の問題点として挙げられているものはどれか。','お金や時間を使いすぎて生活に支障が出ること',['友人が減ること','仕事が増えること','コンサートが少ないこと'],'Masalah.','お金や時間を使いすぎて、生活に支障が出る'),
    ('筆者の考えに合うものはどれか。','生活を壊さない範囲で楽しむことが大切だ',['推し活はやめるべきだ','好きなことに全力で使うべきだ','友人とは行かないほうがよい'],'Pendapat.','自分の生活を壊さない範囲で行うという線引き')]),
 C('日本の企業では、「報告・連絡・相談」、略して「ほうれんそう」が大切だと言われる。上司に仕事の状況を知らせ、困ったときには早めに相談することで、問題が大きくなる前に対処できるという考え方だ。\n　ところが、新入社員の中には、「こんなことを聞いたら、迷惑ではないか」と遠慮して、一人で抱え込んでしまう人がいる。その結果、小さなミスが大きなトラブルに発展することもある。\n　そこで、ある会社では、上司のほうから声をかけ、「困っていることはないか」と尋ねる時間を毎日作ることにした。すると、新入社員が相談しやすくなり、ミスが減ったという。報告や相談は、部下だけの責任ではなく、話しやすい環境を作る上司の工夫も必要だということだ。',
   'Di perusahaan Jepang dikatakan penting "houkoku, renraku, soudan (lapor, kabari, konsultasi)", disingkat "horenso". Pandangannya: dengan memberi tahu atasan kondisi pekerjaan dan berkonsultasi lebih awal saat kesulitan, masalah bisa ditangani sebelum membesar.\n Namun di antara karyawan baru ada yang sungkan "bukankah merepotkan bila bertanya begini" dan menanggung sendirian. Akibatnya kesalahan kecil bisa berkembang jadi masalah besar.\n Maka sebuah perusahaan membuat waktu tiap hari di mana atasan yang menyapa lebih dulu dan menanyakan "adakah yang menyulitkan?". Lalu karyawan baru jadi mudah berkonsultasi dan kesalahan berkurang. Melapor dan berkonsultasi bukan hanya tanggung jawab bawahan, tetapi usaha atasan menciptakan lingkungan yang mudah bicara juga diperlukan.',
   [('「ほうれんそう」の考え方はどれか。','早めに知らせ相談して、問題が大きくなる前に対処する',['問題が起きてから報告する','一人で解決する','上司に任せて何もしない'],'Konsep.','問題が大きくなる前に対処できる'),
    ('新入社員が一人で抱え込む理由は何か。','迷惑ではないかと遠慮するから',['仕事が少ないから','上司がいないから','相談が禁止されているから'],'Sebab.','迷惑ではないかと遠慮して'),
    ('会社が行った工夫の結果はどれか。','新入社員が相談しやすくなり、ミスが減った',['上司の仕事が増えた','新入社員が減った','会議が長くなった'],'Hasil.','相談しやすくなり、ミスが減った')]),
 C('日本には、「もったいない」という言葉がある。物を無駄にすることを惜しむ気持ちを表す言葉で、環境保護の合言葉として、世界にも紹介された。\n　この気持ちは、古くから、日本人の暮らしに根付いていた。着物は、古くなると、布団やぞうきんに作り替えられ、最後は燃料として使われた。一つの物を、形を変えながら、最後まで使い切る知恵があったのである。\n　現代は、安く物が手に入るため、「もったいない」という感覚が薄れつつある。しかし、資源に限りがある以上、この考え方を見直す必要があるだろう。物を買うときに、本当に必要か、長く使えるかを一度考えてみる。そんな小さな習慣が、大きな変化につながるかもしれない。',
   'Di Jepang ada kata "mottainai". Kata yang menyatakan perasaan menyayangkan menyia-nyiakan barang, dan dikenalkan ke dunia sebagai semboyan perlindungan lingkungan.\n Perasaan ini sejak lama mengakar dalam kehidupan orang Jepang. Kimono bila tua diubah jadi kasur dan lap, dan terakhir dipakai sebagai bahan bakar. Ada kearifan memakai habis satu barang sambil mengubah bentuknya.\n Zaman sekarang barang mudah didapat murah sehingga rasa "mottainai" menipis. Namun selama sumber daya terbatas, cara pandang ini perlu ditinjau ulang. Saat membeli barang, coba pikirkan sekali apakah benar-benar perlu dan bisa dipakai lama. Kebiasaan kecil begitu mungkin berujung perubahan besar.',
   [('「もったいない」はどんな気持ちを表すか。','物を無駄にすることを惜しむ気持ち',['物を捨てて喜ぶ気持ち','新しい物を欲しがる気持ち','物を貸す気持ち'],'Makna.','物を無駄にすることを惜しむ気持ち'),
    ('昔の着物の使い方として、合うものはどれか。','布団やぞうきんに作り替え、最後は燃料にした',['古くなるとすぐ捨てた','新しい着物と交換した','博物館に飾った'],'Kimono.','布団やぞうきんに作り替えられ、最後は燃料'),
    ('筆者が勧めている習慣はどれか。','買うときに本当に必要か、長く使えるかを考えること',['安い物をたくさん買うこと','古い物をすべて捨てること','物を買わないこと'],'Saran.','本当に必要か、長く使えるかを一度考えてみる')]),
 C('学校の先生が、授業で生徒に答えを教えずに、質問ばかりする場面を想像してほしい。生徒は最初は戸惑うが、考えるうちに、自分なりの答えを見つけていく。\n　このような授業は、「探究型学習」と呼ばれ、近年、多くの学校で取り入れられている。知識を覚えるだけでなく、自分で問いを立て、調べ、考えを発表する力を育てることを目的としている。\n　ただし、この方法には課題もある。準備や指導に手間がかかるうえ、生徒によっては、何から始めればよいか分からず、立ち止まってしまうことがある。教師は、答えを与えずに、しかし生徒が迷子にならないように、適切な助言をするという難しいバランスが求められる。',
   'Bayangkan guru di kelas tidak memberi jawaban pada murid dan hanya bertanya. Murid awalnya bingung, tetapi sambil berpikir menemukan jawabannya sendiri.\n Pelajaran begini disebut "pembelajaran inkuiri" dan belakangan diterapkan di banyak sekolah. Tujuannya menumbuhkan kemampuan bukan hanya menghafal pengetahuan tetapi menyusun pertanyaan, menyelidiki, dan mempresentasikan pikiran sendiri.\n Namun metode ini punya masalah. Persiapan dan bimbingan merepotkan, dan tergantung murid ada yang tak tahu harus mulai dari mana lalu berhenti. Guru dituntut keseimbangan sulit memberi saran yang tepat tanpa memberi jawaban namun agar murid tak tersesat.',
   [('探究型学習の目的はどれか。','自分で問いを立て、調べ、発表する力を育てること',['知識を暗記させること','試験の点数を上げること','教師の仕事を減らすこと'],'Tujuan.','自分で問いを立て、調べ、考えを発表する力を育てる'),
    ('この方法の課題として挙げられているものはどれか。','準備や指導に手間がかかり、立ち止まる生徒がいること',['生徒が答えを覚えてしまうこと','教師が質問をしなくなること','授業時間が短いこと'],'Masalah.','準備や指導に手間がかかる…立ち止まってしまう'),
    ('教師に求められることは何か。','答えを与えずに、適切な助言をする難しいバランス',['すべての答えを教えること','生徒を放っておくこと','質問をやめること'],'Tuntutan.','答えを与えずに…適切な助言をするという難しいバランス')]),
 C('日本の夏には、各地で花火大会が開かれる。花火は、夜空に一瞬で消えてしまう美しさから、日本人の「はかなさ」を愛する心と結びつけて語られることが多い。\n　しかし、最近の花火大会は、少し様子が変わってきた。音楽に合わせて花火を打ち上げたり、有料の観覧席を設けたりする大会が増えている。観客を楽しませ、運営の費用を集める工夫である。\n　一方で、有料化には、「みんなのものだった花火が、お金を払う人だけのものになる」という批判もある。花火の費用は、年々上がっており、大会を続けるためには、誰かが負担しなければならない。伝統を守ることと、続けるための現実的な工夫との間で、各地の主催者は悩んでいる。',
   'Pada musim panas Jepang, berbagai daerah mengadakan festival kembang api. Kembang api dari keindahannya yang lenyap sekejap di langit malam sering dikaitkan dengan hati orang Jepang yang menyukai "kefanaan".\n Namun festival belakangan agak berubah. Bertambah festival yang meluncurkan kembang api mengikuti musik atau menyediakan tempat tonton berbayar. Itu upaya menghibur penonton dan mengumpulkan biaya penyelenggaraan.\n Di sisi lain ada kritik pada pembayaran "kembang api yang tadinya milik semua jadi milik yang bayar saja". Biaya kembang api naik tiap tahun, dan agar festival berlanjut ada yang harus menanggung. Penyelenggara di berbagai daerah bimbang antara menjaga tradisi dan upaya realistis untuk melanjutkannya.',
   [('花火が「はかなさ」と結びつけられるのはなぜか。','夜空に一瞬で消えてしまう美しさがあるから',['値段が高いから','音が大きいから','夏にしか見られないから'],'Alasan.','夜空に一瞬で消えてしまう美しさ'),
    ('最近の花火大会で増えているものはどれか。','音楽に合わせた打ち上げや有料の観覧席',['無料の大会','昼間の大会','小さな花火だけの大会'],'Tren.','音楽に合わせて…有料の観覧席を設けたり'),
    ('主催者が悩んでいることは何か。','伝統を守ることと、続けるための現実的な工夫との間',['花火の種類が少ないこと','観客が来ないこと','夏が短いこと'],'Dilema.','伝統を守ることと、続けるための現実的な工夫との間')]),
 C('健康のために、毎日一万歩を歩くとよいと言われる。しかし、最近の研究では、必ずしも一万歩を歩く必要はなく、それより少ない歩数でも、十分な効果があることが分かってきた。\n　ある調査では、一日に七千歩程度を歩く人は、四千歩程度の人に比べて、病気になる危険が低かった。一方、七千歩を超えて歩いても、効果の差は小さくなったという。\n　大切なのは、無理のない範囲で、続けることだ。「一万歩」という数字に縛られて、できない日に自分を責めてしまうと、かえって運動が嫌になってしまう。まずは、今より少し多く歩くことを目標にするのが、長続きのこつだろう。',
   'Demi kesehatan dikatakan baik berjalan sepuluh ribu langkah tiap hari. Namun penelitian belakangan menunjukkan tak selalu perlu sepuluh ribu langkah, dan dengan langkah lebih sedikit pun efeknya cukup.\n Dalam suatu survei, orang yang berjalan sekitar tujuh ribu langkah sehari risiko sakitnya lebih rendah dibanding yang sekitar empat ribu. Sebaliknya, walau berjalan melebihi tujuh ribu, selisih efeknya mengecil.\n Yang penting melanjutkan dalam batas tak memaksa. Jika terikat angka "sepuluh ribu" dan menyalahkan diri di hari tak sanggup, malah jadi benci olahraga. Pertama-tama menargetkan berjalan sedikit lebih banyak dari sekarang adalah kunci bertahan lama.',
   [('最近の研究で分かったことは何か。','一万歩より少なくても十分な効果がある',['一万歩以上でないと効果がない','歩いても効果がない','歩数が多いほど効果が増え続ける'],'Temuan.','それより少ない歩数でも、十分な効果'),
    ('調査の結果として合うものはどれか。','七千歩を超えると、効果の差は小さくなった',['四千歩の人のほうが危険が低かった','七千歩を超えると効果が急に増えた','歩数と病気は無関係だった'],'Survei.','七千歩を超えて歩いても、効果の差は小さく'),
    ('長続きのこつとして筆者が勧めているのはどれか。','今より少し多く歩くことを目標にする',['毎日必ず一万歩歩く','できない日は自分を責める','運動を週に一度にする'],'Kunci.','今より少し多く歩くことを目標に')]),
 C('日本の伝統的な家には、「縁側」と呼ばれる、庭に面した細長い板張りの空間がある。家の中でも外でもない、あいまいな場所だ。\n　縁側は、日常の中で、さまざまな役割を果たしてきた。日当たりのよい場所で、お茶を飲んだり、昼寝をしたりする。近所の人が訪ねてくれば、玄関まで回らなくても、縁側に腰かけて、気軽に話ができる。\n　現代の住宅では、縁側を持つ家は少なくなったが、最近、その価値が見直されている。人と人との距離を、ほどよく保ちながらつながることができる場所として、集合住宅や施設に、縁側のような空間を作る試みが広がっているのだ。',
   'Rumah tradisional Jepang punya ruang papan sempit menghadap taman bernama "engawa". Ruang samar yang bukan di dalam maupun di luar rumah.\n Engawa menjalankan berbagai peran dalam kehidupan sehari-hari. Di tempat yang terkena matahari, orang minum teh atau tidur siang. Bila tetangga berkunjung, tanpa memutar ke pintu depan bisa duduk di engawa dan berbincang santai.\n Di hunian modern rumah beserta engawa berkurang, tetapi belakangan nilainya ditinjau ulang. Sebagai tempat yang bisa terhubung sambil menjaga jarak antarorang secukupnya, upaya membuat ruang seperti engawa di apartemen dan fasilitas meluas.',
   [('縁側とはどんな場所か。','家の中でも外でもない、庭に面した空間',['家の一番奥の部屋','庭の中の小屋','玄関の中の部屋'],'Definisi.','家の中でも外でもない、あいまいな場所'),
    ('縁側で近所の人はどうできるか。','玄関まで回らず、腰かけて気軽に話せる',['家の中で食事をする','玄関から入って話す','庭に入れない'],'Fungsi.','玄関まで回らなくても…気軽に話ができる'),
    ('縁側の価値が見直されているのはなぜか。','人との距離をほどよく保ちながらつながれるから',['日当たりがよいから','家が広くなるから','工事が簡単だから'],'Alasan.','距離を、ほどよく保ちながらつながることができる')]),
 C('「働き方改革」が進む中、多くの会社が残業を減らす努力をしている。確かに、長時間働くことが、必ずしも成果につながるとは限らない。\n　しかし、現場からは、「仕事の量は変わらないのに、時間だけ短くなった」という声も聞かれる。残業を禁止しても、仕事を持ち帰ったり、休日に出勤したりする人が出てくれば、本末転倒である。\n　本当に必要なのは、時間を減らすことと同時に、仕事のやり方そのものを見直すことだ。会議を短くする、不要な書類をなくすなど、無駄を減らさなければ、改革は形だけで終わってしまう。働く人が、自分の時間を大切にしながら、きちんと成果を出せる環境を、会社全体で考えるべきだ。',
   'Di tengah kemajuan "reformasi cara kerja", banyak perusahaan berupaya mengurangi lembur. Memang bekerja lama tak selalu berujung hasil.\n Namun dari lapangan terdengar suara "jumlah pekerjaan tak berubah, hanya waktunya yang diperpendek". Bila lembur dilarang tetapi ada yang membawa pulang pekerjaan atau masuk di hari libur, itu mengabaikan pokok.\n Yang benar-benar diperlukan adalah, bersamaan dengan mengurangi waktu, meninjau cara kerja itu sendiri. Bila tak mengurangi pemborosan seperti mempersingkat rapat dan menghilangkan dokumen tak perlu, reformasi hanya jadi formalitas. Seluruh perusahaan harus memikirkan lingkungan di mana pekerja bisa menghargai waktunya sambil menghasilkan dengan baik.',
   [('現場からどんな声が聞かれるか。','仕事の量は変わらないのに、時間だけ短くなった',['残業が増えた','仕事が減りすぎた','給料が上がった'],'Suara lapangan.','仕事の量は変わらないのに、時間だけ短くなった'),
    ('「本末転倒」とは、ここではどんな状態か。','残業を禁止したのに、仕事を持ち帰ったり休日に出勤したりする状態',['残業が減って成果も上がる状態','会社が改革をしない状態','休日が増えた状態'],'Honmatsu tentou.','仕事を持ち帰ったり、休日に出勤したり'),
    ('筆者が本当に必要だと言っていることは何か。','時間を減らすと同時に、仕事のやり方自体を見直すこと',['残業を完全に禁止すること','会議を増やすこと','社員を増やすこと'],'Inti.','仕事のやり方そのものを見直す')]),
 C('ペットを飼うことは、心を癒やし、生活に楽しみを与えてくれる。しかし、最近、飼い主が飼えなくなって、捨ててしまう例が問題になっている。\n　動物を飼う前に、考えるべきことは多い。毎日の世話に時間がかかるだけでなく、病気になったときの医療費も必要だ。犬や猫は、十五年以上生きることもあり、その間、責任を持って世話を続けなければならない。\n　そこで、ある自治体は、ペットを飼いたい人に、事前に講習を受けてもらう制度を始めた。飼うことの責任の重さを知ったうえで、それでも飼いたいと思う人だけが飼う。それが、動物にとっても、人にとっても、幸せな関係を作る第一歩だと考えているのだ。',
   'Memelihara hewan menenangkan hati dan memberi kesenangan hidup. Namun belakangan kasus pemilik yang tak sanggup memelihara lalu membuangnya menjadi masalah.\n Sebelum memelihara hewan banyak yang harus dipikirkan. Selain perawatan harian memakan waktu, biaya pengobatan saat sakit juga diperlukan. Anjing dan kucing kadang hidup lebih dari lima belas tahun dan selama itu harus dirawat dengan tanggung jawab.\n Karena itu sebuah pemda memulai sistem agar orang yang ingin memelihara hewan mengikuti kursus lebih dulu. Hanya orang yang tahu beratnya tanggung jawab dan tetap ingin memelihara yang memelihara. Itu dianggap langkah pertama membangun hubungan bahagia bagi hewan maupun manusia.',
   [('最近、問題になっていることは何か。','飼い主が飼えなくなって捨ててしまうこと',['ペットが増えすぎること','ペットが高いこと','ペットが病気にならないこと'],'Masalah.','飼えなくなって、捨ててしまう例'),
    ('動物を飼う前に考えるべきこととして、文章に合うものはどれか。','毎日の世話の時間と医療費、長く世話を続ける責任',['ペットの値段だけ','かわいいかどうか','近所の人の意見'],'Pertimbangan.','世話に時間がかかる…医療費…責任を持って世話を続け'),
    ('自治体が始めた制度の目的は何か。','責任の重さを知ったうえで飼う人だけが飼うようにすること',['ペットを安く売ること','ペットの数を増やすこと','飼い主に料金を払わせること'],'Tujuan.','責任の重さを知ったうえで…それでも飼いたいと思う人だけが飼う')]),
 C('友人関係において、「相手に合わせすぎてしまう」という悩みを持つ人は多い。嫌われたくないために、自分の意見を飲み込んでしまうのだ。\n　しかし、いつも相手に合わせていると、自分が何をしたいのか分からなくなり、疲れがたまってしまう。しかも、相手から見れば、「この人は何を考えているのか分からない」と、かえって距離を感じさせることもある。\n　大切なのは、相手を尊重しながらも、自分の気持ちを素直に伝えることだ。意見が違っても、「そういう考えもあるね」と受け止めたうえで、自分の考えを話せば、関係はむしろ深まる。本当の友人は、違いを認め合える関係の中で育つのだと思う。',
   'Dalam pertemanan banyak orang punya kerisauan "terlalu menyesuaikan diri dengan lawan". Karena tak ingin dibenci, mereka menelan pendapat sendiri.\n Namun bila selalu menyesuaikan, jadi tak tahu apa yang ingin dilakukan sendiri dan kelelahan menumpuk. Bahkan dari sudut lawan, bisa terasa "tak tahu apa yang dipikirkan orang ini" sehingga malah terasa berjarak.\n Yang penting menyampaikan perasaan sendiri dengan jujur sambil menghormati lawan. Meski pendapat berbeda, bila menerima "ada pemikiran begitu juga ya" lalu menyampaikan pikiran sendiri, hubungan justru mendalam. Saya kira teman sejati tumbuh dalam hubungan yang bisa saling mengakui perbedaan.',
   [('相手に合わせすぎる人は、なぜ意見を言わないのか。','嫌われたくないから',['意見がないから','相手が怖いから','時間がないから'],'Sebab.','嫌われたくないために、自分の意見を飲み込んでしまう'),
    ('いつも相手に合わせるとどうなるか。','自分のしたいことが分からなくなり、疲れがたまる',['相手と仲良くなれる','意見が増える','疲れがなくなる'],'Akibat.','自分が何をしたいのか分からなくなり、疲れがたまって'),
    ('筆者の考えに合うものはどれか。','違いを認め合える関係の中で本当の友人が育つ',['意見は言わないほうがよい','相手と違う意見は避けるべきだ','友人は少ないほうがよい'],'Pendapat.','違いを認め合える関係の中で育つ')]),
]
